import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type Language = 'en' | 'si';

export enum AppView {
  ONBOARDING = 'ONBOARDING',
  DASHBOARD = 'DASHBOARD',
  CHAT = 'CHAT',
  MEDITATION = 'MEDITATION',
  JOURNAL = 'JOURNAL',
  SUTTA = 'SUTTA',
  TEMPLE = 'TEMPLE'
}

export interface UserPreferences {
  hasCompletedOnboarding: boolean;
  language: Language;
  goals: string[];
  receiveDailyDrops: boolean;
  name?: string;
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'model';
  text: string;
  timestamp: number;
}

export interface JournalEntry {
  id: string;
  date: string;
  content: string;
  mood?: 'peaceful' | 'neutral' | 'restless';
  tags: string[];
}

export interface DailyDrop {
  quote: string;
  source: string;
  reflection: string;
}

import { GoogleGenAI, Chat, GenerateContentResponse } from "@google/genai";
import { Language, DailyDrop } from "../types";

// NOTE: In a real production app, ensure API keys are handled securely.
// For this demo, we assume process.env.API_KEY is available.
const apiKey = process.env.API_KEY || 'DUMMY_KEY_FOR_DEMO';

const ai = new GoogleGenAI({ apiKey });

export const createChatSession = (language: Language, userGoals: string[]): Chat => {
  const systemInstruction = `
    You are Bhante Bodhi, a wise, compassionate, and gentle Theravāda Buddhist monk.
    Your goal is to guide the user on their spiritual path.
    The user's goals are: ${userGoals.join(', ')}.

    Guidelines:
    1. Respond with reverence, clarity, and compassion.
    2. Base your answers on the Pali Canon (Tipitaka).
    3. Use simple metaphors where possible.
    4. If the user asks in Sinhala, respond in Sinhala. If in English, respond in English.
    5. Be non-judgmental and encouraging.
    6. Do not claim to be enlightened; speak as a humble guide.
    7. Current language preference of user: ${language === 'si' ? 'Sinhala' : 'English'}.
  `;

  return ai.chats.create({
    model: 'gemini-3-flash-preview',
    config: {
      systemInstruction: systemInstruction,
      thinkingConfig: { thinkingBudget: 0 } 
    },
  });
};

export const generateDailyDharma = async (language: Language): Promise<DailyDrop> => {
  try {
    const prompt = language === 'si' 
      ? "Provide a short, inspiring quote from the Theravāda Buddhist Pali Canon in Sinhala, followed by its source (Sutta name), and a very brief 1-sentence reflection for daily life." 
      : "Provide a short, inspiring quote from the Theravāda Buddhist Pali Canon in English, followed by its source (Sutta name), and a very brief 1-sentence reflection for daily life.";

    // Using JSON schema to ensure structured output
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
            type: "OBJECT",
            properties: {
                quote: { type: "STRING" },
                source: { type: "STRING" },
                reflection: { type: "STRING" }
            },
            required: ["quote", "source", "reflection"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("No content generated");

    return JSON.parse(text) as DailyDrop;
  } catch (error) {
    console.error("Error generating daily dharma:", error);
    // Fallback content if API fails or key is missing
    return {
      quote: language === 'si' 
        ? "සියලු සංස්කාර ධර්මයෝ නැසෙන සුලුය. අප්‍රමාදව කුසල් දහම්හි යෙදෙන්න." 
        : "All conditioned things are impermanent. Strive on with diligence.",
      source: "Mahaparinibbana Sutta (DN 16)",
      reflection: language === 'si' 
        ? "සෑම මොහොතක්ම අගනේය, එය යහපත සඳහා යොදවන්න." 
        : "Cherish every moment and use it to cultivate goodness."
    };
  }
};

export const getMeditationGuide = async (type: string, duration: number, language: Language): Promise<string> => {
    // Generate a short intro/guide for meditation
    const prompt = `Write a short, calming introduction for a ${duration}-minute ${type} meditation session in ${language === 'si' ? 'Sinhala' : 'English'}. Keep it under 50 words.`;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
        });
        return response.text || "Breathe in, breathe out. Relax your mind.";
    } catch (e) {
        return language === 'si' ? "සුවපහසු ඉරියව්වක් ගන්න. ඔබේ හුස්ම කෙරෙහි අවධානය යොමු කරන්න." : "Find a comfortable posture. Focus gently on your breath.";
    }
}

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ChevronRight, Check } from 'lucide-react';
import { UI_TEXT, GOAL_OPTIONS } from '../constants';
import { UserPreferences, Language } from '../types';

interface OnboardingProps {
  onComplete: (prefs: UserPreferences) => void;
}

const Onboarding: React.FC<OnboardingProps> = ({ onComplete }) => {
  const [step, setStep] = useState(1);
  const [language, setLanguage] = useState<Language>('en');
  const [goals, setGoals] = useState<string[]>([]);
  const [receiveDailyDrops, setReceiveDailyDrops] = useState(true);

  const t = UI_TEXT[language];
  const goalOpts = GOAL_OPTIONS[language];

  const handleNext = () => setStep(prev => prev + 1);

  const toggleGoal = (goal: string) => {
    setGoals(prev => 
      prev.includes(goal) ? prev.filter(g => g !== goal) : [...prev, goal]
    );
  };

  const finishOnboarding = () => {
    onComplete({
      hasCompletedOnboarding: true,
      language,
      goals,
      receiveDailyDrops,
    });
  };

  const containerVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: { opacity: 1, y: 0 },
    exit: { opacity: 0, x: -20 }
  };

  return (
    <div className="min-h-screen bg-stone-100 flex items-center justify-center p-6 relative overflow-hidden">
      {/* Background Decor */}
      <div className="absolute top-0 left-0 w-full h-full pointer-events-none opacity-10">
         <svg viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg" className="absolute top-[-50px] right-[-50px] w-96 h-96 fill-orange-300">
            <path d="M44.7,-76.4C58.9,-69.2,71.8,-59.1,81.6,-46.7C91.4,-34.3,98.1,-19.6,95.8,-5.8C93.5,8,82.2,21,71.6,32.1C61,43.2,51.1,52.4,40,60.2C28.9,68,16.6,74.4,2.9,79.4C-10.8,84.4,-25.9,88.1,-39.3,83.3C-52.7,78.5,-64.4,65.2,-73.4,50.7C-82.4,36.2,-88.7,20.5,-88.1,5.2C-87.5,-10.1,-80,-25,-69.8,-37.7C-59.6,-50.4,-46.7,-60.9,-33.4,-68.6C-20.1,-76.3,-6.4,-81.2,5.2,-90.2L16.8,-99.2" transform="translate(100 100)" />
         </svg>
      </div>

      <div className="w-full max-w-md z-10">
        <AnimatePresence mode="wait">

          {/* Step 1: Welcome */}
          {step === 1 && (
            <motion.div
              key="step1"
              variants={containerVariants}
              initial="hidden"
              animate="visible"
              exit="exit"
              className="bg-white rounded-3xl p-8 shadow-xl text-center"
            >
              <div className="mb-6 flex justify-center">
                <span className="text-6xl">🌼</span>
              </div>
              <h1 className="text-3xl font-serif text-stone-800 mb-4 font-bold">BodhiPath</h1>
              <p className="text-stone-600 mb-8 leading-relaxed font-serif italic">
                {language === 'si' ? UI_TEXT.si.subtitle : UI_TEXT.en.subtitle}
              </p>
              <button 
                onClick={handleNext}
                className="w-full bg-orange-600 hover:bg-orange-700 text-white py-3 rounded-full font-medium transition-all shadow-lg shadow-orange-200"
              >
                {language === 'si' ? UI_TEXT.si.startBtn : UI_TEXT.en.startBtn}
              </button>
              <div className="mt-4 flex justify-center space-x-4 text-sm text-stone-400">
                <button onClick={() => setLanguage('en')} className={language === 'en' ? 'text-orange-600 font-bold' : ''}>English</button>
                <span>|</span>
                <button onClick={() => setLanguage('si')} className={language === 'si' ? 'text-orange-600 font-bold' : ''}>සිංහල</button>
              </div>
            </motion.div>
          )}

          {/* Step 2: Language (Redundant but keeps flow explicitly confirmed) */}
          {step === 2 && (
            <motion.div
               key="step2"
               variants={containerVariants}
               initial="hidden"
               animate="visible"
               exit="exit"
               className="bg-white rounded-3xl p-8 shadow-xl"
            >
               <h2 className={`text-2xl font-serif text-stone-800 mb-6 ${language === 'si' ? 'font-sinhala' : ''}`}>
                 {t.langSelect}
               </h2>
               <div className="space-y-4">
                 <button 
                   onClick={() => { setLanguage('en'); handleNext(); }}
                   className={`w-full p-4 rounded-2xl border-2 flex items-center justify-between transition-all ${language === 'en' ? 'border-orange-500 bg-orange-50' : 'border-stone-200 hover:border-orange-200'}`}
                 >
                   <span className="text-lg">English</span>
                   {language === 'en' && <Check className="text-orange-500" />}
                 </button>
                 <button 
                   onClick={() => { setLanguage('si'); handleNext(); }}
                   className={`w-full p-4 rounded-2xl border-2 flex items-center justify-between transition-all font-sinhala ${language === 'si' ? 'border-orange-500 bg-orange-50' : 'border-stone-200 hover:border-orange-200'}`}
                 >
                   <span className="text-lg">සිංහල</span>
                   {language === 'si' && <Check className="text-orange-500" />}
                 </button>
               </div>
            </motion.div>
          )}

          {/* Step 3: Goals */}
          {step === 3 && (
            <motion.div
               key="step3"
               variants={containerVariants}
               initial="hidden"
               animate="visible"
               exit="exit"
               className="bg-white rounded-3xl p-8 shadow-xl"
            >
               <h2 className={`text-2xl font-serif text-stone-800 mb-6 ${language === 'si' ? 'font-sinhala' : ''}`}>
                 {t.goalsTitle}
               </h2>
               <div className="space-y-3 mb-8">
                 {goalOpts.map((goal) => (
                   <button 
                     key={goal}
                     onClick={() => toggleGoal(goal)}
                     className={`w-full text-left p-4 rounded-xl border flex items-center transition-all ${goals.includes(goal) ? 'bg-orange-50 border-orange-500 text-orange-900' : 'border-stone-200 text-stone-600 hover:bg-stone-50'}`}
                   >
                     <div className={`w-5 h-5 rounded-full border mr-3 flex items-center justify-center ${goals.includes(goal) ? 'bg-orange-500 border-orange-500' : 'border-stone-300'}`}>
                        {goals.includes(goal) && <Check size={12} className="text-white" />}
                     </div>
                     <span className={language === 'si' ? 'font-sinhala' : ''}>{goal}</span>
                   </button>
                 ))}
               </div>
               <button 
                onClick={handleNext}
                disabled={goals.length === 0}
                className="w-full bg-stone-800 disabled:opacity-50 text-white py-3 rounded-full flex items-center justify-center space-x-2"
              >
                <span>Next</span>
                <ChevronRight size={16} />
              </button>
            </motion.div>
          )}

          {/* Step 4: Personalization */}
          {step === 4 && (
             <motion.div
                key="step4"
                variants={containerVariants}
                initial="hidden"
                animate="visible"
                exit="exit"
                className="bg-white rounded-3xl p-8 shadow-xl"
             >
                <h2 className={`text-2xl font-serif text-stone-800 mb-6 ${language === 'si' ? 'font-sinhala' : ''}`}>
                  {t.personalizeTitle}
                </h2>
                <div className="space-y-4 mb-8">
                   <button onClick={handleNext} className="w-full p-4 bg-orange-100 text-orange-900 rounded-xl font-medium hover:bg-orange-200 transition-colors">
                     {language === 'si' ? 'ඔව්, මග පෙන්වන්න' : 'Yes, guide me'}
                   </button>
                   <button onClick={handleNext} className="w-full p-4 bg-stone-100 text-stone-600 rounded-xl font-medium hover:bg-stone-200 transition-colors">
                     {language === 'si' ? 'නැහැ, මමම සොයන්නම්' : 'No, I’ll explore freely'}
                   </button>
                </div>
             </motion.div>
          )}

           {/* Step 5: Daily Drops */}
           {step === 5 && (
             <motion.div
                key="step5"
                variants={containerVariants}
                initial="hidden"
                animate="visible"
                exit="exit"
                className="bg-white rounded-3xl p-8 shadow-xl"
             >
                <h2 className={`text-2xl font-serif text-stone-800 mb-6 ${language === 'si' ? 'font-sinhala' : ''}`}>
                  {t.dailyDropTitle}
                </h2>
                <div className="flex space-x-4 mb-8">
                   <button onClick={() => { setReceiveDailyDrops(true); handleNext(); }} className="flex-1 p-6 bg-white border-2 border-stone-200 hover:border-orange-400 rounded-2xl flex flex-col items-center justify-center gap-2 transition-all">
                      <span className="text-3xl">🌞</span>
                      <span className="font-bold text-stone-700">{language === 'si' ? 'ඔව්' : 'Yes'}</span>
                   </button>
                   <button onClick={() => { setReceiveDailyDrops(false); handleNext(); }} className="flex-1 p-6 bg-white border-2 border-stone-200 hover:border-stone-400 rounded-2xl flex flex-col items-center justify-center gap-2 transition-all">
                      <span className="text-3xl">🌑</span>
                      <span className="font-bold text-stone-700">{language === 'si' ? 'නැහැ' : 'No'}</span>
                   </button>
                </div>
             </motion.div>
          )}

          {/* Step 6: Final */}
          {step === 6 && (
             <motion.div
                key="step6"
                variants={containerVariants}
                initial="hidden"
                animate="visible"
                exit="exit"
                className="bg-white rounded-3xl p-8 shadow-xl text-center"
             >
                <div className="mb-6 flex justify-center">
                  <span className="text-6xl animate-pulse">🌸</span>
                </div>
                <h2 className={`text-2xl font-serif text-stone-800 mb-2 font-bold ${language === 'si' ? 'font-sinhala' : ''}`}>
                  {t.finalTitle}
                </h2>
                <p className={`text-stone-600 mb-8 ${language === 'si' ? 'font-sinhala' : ''}`}>
                  {t.finalSubtitle}
                </p>
                <button 
                  onClick={finishOnboarding}
                  className="w-full bg-orange-600 hover:bg-orange-700 text-white py-4 rounded-full font-bold text-lg transition-all shadow-xl shadow-orange-200"
                >
                  {t.enterBtn}
                </button>
             </motion.div>
          )}

        </AnimatePresence>
      </div>
    </div>
  );
};

export default Onboarding;

import React, { useState, useRef, useEffect } from 'react';
import { Send, User, Bot, Loader2, Sparkles } from 'lucide-react';
import { ChatMessage, Language } from '../types';
import { createChatSession } from '../services/geminiService';
import { UI_TEXT } from '../constants';
import { Chat } from '@google/genai';

interface ChatInterfaceProps {
  language: Language;
  userGoals: string[];
}

const ChatInterface: React.FC<ChatInterfaceProps> = ({ language, userGoals }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [chatSession, setChatSession] = useState<Chat | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const t = UI_TEXT[language];

  useEffect(() => {
    // Initialize session
    const session = createChatSession(language, userGoals);
    setChatSession(session);

    // Initial greeting
    setMessages([{
        id: 'init',
        role: 'model',
        text: language === 'si' 
            ? "තෙරුවන් සරණයි! මම භන්තේ බෝධි. ඔබට ධර්මය සම්බන්ධව ඇති ගැටලු මොනවාද?"
            : "Namo Buddhaya! I am Bhante Bodhi. How may I guide you on the Dhamma path today?",
        timestamp: Date.now()
    }]);
  }, [language, userGoals]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || !chatSession) return;

    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      text: input,
      timestamp: Date.now()
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    try {
      const result = await chatSession.sendMessage({ message: userMsg.text });
      const text = result.text; // Access text directly from property

      const botMsg: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: text || (language === 'si' ? "මට එය තේරුම් ගැනීමට අපහසුයි. කරුණාකර නැවත අසන්න." : "I apologize, I could not understand clearly. Please ask again."),
        timestamp: Date.now()
      };
      setMessages(prev => [...prev, botMsg]);
    } catch (error) {
      console.error("Chat error:", error);
      const errorMsg: ChatMessage = {
         id: (Date.now() + 1).toString(),
         role: 'model',
         text: language === 'si' ? "සමාවන්න, තාක්ෂණික දෝෂයක් සිදු විය." : "Apologies, I encountered a disturbance. Please try again.",
         timestamp: Date.now()
      };
      setMessages(prev => [...prev, errorMsg]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="flex flex-col h-full bg-stone-50 rounded-2xl overflow-hidden shadow-inner border border-stone-200">
      {/* Header */}
      <div className="bg-orange-100 p-4 flex items-center border-b border-orange-200">
        <div className="w-10 h-10 rounded-full bg-orange-200 flex items-center justify-center mr-3 border-2 border-white">
             <span className="text-xl">🧘‍♂️</span>
        </div>
        <div>
          <h3 className={`font-serif font-bold text-stone-800 ${language === 'si' ? 'font-sinhala' : ''}`}>{t.monkPersona}</h3>
          <p className="text-xs text-stone-600 flex items-center">
            <Sparkles size={10} className="mr-1 text-orange-500" /> 
            AI Guide (Gemini)
          </p>
        </div>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.map((msg) => (
          <div 
            key={msg.id} 
            className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
          >
            <div className={`max-w-[80%] rounded-2xl p-4 shadow-sm ${
              msg.role === 'user' 
                ? 'bg-orange-600 text-white rounded-tr-none' 
                : 'bg-white text-stone-800 border border-stone-100 rounded-tl-none font-serif'
            }`}>
                <p className={`whitespace-pre-wrap leading-relaxed ${language === 'si' ? 'font-sinhala' : ''}`}>{msg.text}</p>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
             <div className="bg-white rounded-2xl rounded-tl-none p-4 shadow-sm border border-stone-100 flex items-center space-x-2">
                <Loader2 size={16} className="animate-spin text-orange-500" />
                <span className="text-sm text-stone-400 italic">Thinking...</span>
             </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input */}
      <div className="p-4 bg-white border-t border-stone-200">
        <div className="flex items-center space-x-2 bg-stone-100 rounded-full px-4 py-2 border border-transparent focus-within:border-orange-300 focus-within:bg-white transition-all">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder={t.chatPlaceholder}
            className={`flex-1 bg-transparent border-none focus:outline-none text-stone-800 placeholder-stone-400 ${language === 'si' ? 'font-sinhala' : ''}`}
            disabled={isLoading}
          />
          <button 
            onClick={handleSend} 
            disabled={isLoading || !input.trim()}
            className="p-2 bg-orange-600 text-white rounded-full hover:bg-orange-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
          >
            <Send size={18} />
          </button>
        </div>
      </div>
    </div>
  );
};

export default ChatInterface;

import React, { useState, useEffect } from 'react';
import { Play, Pause, Square, Wind } from 'lucide-react';
import { Language } from '../types';
import { getMeditationGuide } from '../services/geminiService';
import { UI_TEXT } from '../constants';

interface MeditationHallProps {
  language: Language;
}

const MeditationHall: React.FC<MeditationHallProps> = ({ language }) => {
  const [duration, setDuration] = useState(5); // Minutes
  const [timeLeft, setTimeLeft] = useState(duration * 60);
  const [isActive, setIsActive] = useState(false);
  const [guidance, setGuidance] = useState<string>('');
  const [loadingGuidance, setLoadingGuidance] = useState(false);

  const t = UI_TEXT[language];

  useEffect(() => {
    setTimeLeft(duration * 60);
  }, [duration]);

  useEffect(() => {
    let interval: NodeJS.Timeout | null = null;
    if (isActive && timeLeft > 0) {
      interval = setInterval(() => {
        setTimeLeft((prev) => prev - 1);
      }, 1000);
    } else if (timeLeft === 0) {
      setIsActive(false);
      if (interval) clearInterval(interval);
      // Play a gentle bell sound here if possible (Audio API)
    }
    return () => {
      if (interval) clearInterval(interval);
    };
  }, [isActive, timeLeft]);

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const handleStart = async () => {
    if (timeLeft === duration * 60 && !guidance) {
        setLoadingGuidance(true);
        const text = await getMeditationGuide('Mindfulness', duration, language);
        setGuidance(text);
        setLoadingGuidance(false);
    }
    setIsActive(true);
  };

  const toggleTimer = () => {
    if (!isActive) {
        handleStart();
    } else {
        setIsActive(false);
    }
  };

  const resetTimer = () => {
    setIsActive(false);
    setTimeLeft(duration * 60);
    setGuidance('');
  };

  return (
    <div className="flex flex-col items-center justify-center h-full p-6 bg-gradient-to-br from-stone-50 to-orange-50 rounded-2xl shadow-inner text-center">

      <div className="mb-8">
        <h2 className={`text-3xl font-serif text-stone-800 mb-2 ${language === 'si' ? 'font-sinhala' : ''}`}>
           {isActive ? (language === 'si' ? 'හුස්ම ගන්න...' : 'Breathe...') : (language === 'si' ? 'භාවනා ශාලාව' : 'Meditation Hall')}
        </h2>
        <p className="text-stone-500 flex items-center justify-center gap-2">
            <Wind size={16} /> 
            {language === 'si' ? 'මනස සන්සුන් කරගන්න' : 'Calm the mind'}
        </p>
      </div>

      {/* Timer Circle */}
      <div className="relative w-64 h-64 mb-8">
         <svg className="w-full h-full transform -rotate-90">
             <circle
               cx="128"
               cy="128"
               r="120"
               stroke="currentColor"
               strokeWidth="8"
               fill="transparent"
               className="text-stone-200"
             />
             <circle
               cx="128"
               cy="128"
               r="120"
               stroke="currentColor"
               strokeWidth="8"
               fill="transparent"
               strokeDasharray={2 * Math.PI * 120}
               strokeDashoffset={2 * Math.PI * 120 * (1 - timeLeft / (duration * 60))}
               className="text-orange-400 transition-all duration-1000 ease-linear"
             />
         </svg>
         <div className="absolute top-0 left-0 w-full h-full flex items-center justify-center flex-col">
            <span className="text-5xl font-mono text-stone-700 font-bold">{formatTime(timeLeft)}</span>
         </div>
      </div>

      {/* Controls */}
      <div className="flex items-center space-x-6 mb-8">
        {!isActive ? (
             <button onClick={toggleTimer} className="w-16 h-16 bg-orange-600 rounded-full flex items-center justify-center text-white shadow-lg hover:bg-orange-700 transition-all transform hover:scale-105">
                <Play fill="currentColor" />
             </button>
        ) : (
             <button onClick={toggleTimer} className="w-16 h-16 bg-stone-200 rounded-full flex items-center justify-center text-stone-700 shadow-lg hover:bg-stone-300 transition-all">
