      {/* Guidance */}
      <div className="max-w-md w-full min-h-[80px]">
          {loadingGuidance ? (
              <p className="text-stone-400 italic animate-pulse">Preparing guidance...</p>
          ) : (
            guidance && (
                <div className="bg-white/80 p-4 rounded-xl border border-orange-100 shadow-sm">
