import React, { useState } from 'react';
import Onboarding from './components/Onboarding';
import Dashboard from './components/Dashboard';
import { UserPreferences } from './types';

function App() {
  // Initialize state from localStorage to remember user selection
  const [preferences, setPreferences] = useState<UserPreferences | null>(() => {
    try {
      const saved = localStorage.getItem('bodhi_prefs');
      return saved ? JSON.parse(saved) : null;
    } catch (e) {
      console.error("Failed to load preferences", e);
      return null;
    }
  });

  const handleOnboardingComplete = (prefs: UserPreferences) => {
    setPreferences(prefs);
    // Save to localStorage so data persists across reloads
    localStorage.setItem('bodhi_prefs', JSON.stringify(prefs));
  };

  const handleReset = () => {
    // Clear data to allow user to restart onboarding
    localStorage.removeItem('bodhi_prefs');
    setPreferences(null);
  };

  return (
    <div className="h-screen w-full bg-stone-50 text-stone-800 font-sans">
      {!preferences ? (
        <Onboarding onComplete={handleOnboardingComplete} />
      ) : (
        <Dashboard preferences={preferences} onReset={handleReset} />
      )}
    </div>
  );
}

