    <content><![CDATA[import React, { useState, useEffect, useCallback } from "react";
import { Loader2 } from "lucide-react";
import { Auth } from "./components/Auth";
import { Dashboard } from "./components/Dashboard";
import { UserPreferences } from "./types";
import { auth, loadUserPreferences, saveUserPreferences, isFirebaseConfigured } from "./services/firebase";
import { onAuthStateChanged } from "firebase/auth";

function App() {
  const [user, setUser] = useState(null);
  const [preferences, setPreferences] = useState<UserPreferences | null>(null);
  const [loading, setLoading] = useState(true);
  const [isGuest, setIsGuest] = useState(false);

  // Load preferences from local storage or Firestore on app start
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (user) => {
      setUser(user);
      if (user) {
        // Load from Firestore if user is logged in
        try {
          const prefs = await loadUserPreferences(user.uid);
          setPreferences(prefs);
        } catch (e) {
          console.error("Error loading user preferences from Firestore:", e);
          setPreferences(null);
        }
      } else {
        // Load from local storage if user is not logged in (guest mode)
        try {
            const saved = localStorage.getItem('bodhi_prefs');
            if (saved) {
                setPreferences(JSON.parse(saved));
            } else {
                setPreferences(null);
            }
          } catch (e) {
              setPreferences(null);
          }
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const handleOnboardingComplete = async (prefs: UserPreferences) => {
    setPreferences(prefs);
    if (user && !isGuest) {
        // Save to Firestore
        await saveUserPreferences(user.uid, prefs);
    } else {
        // Save to LocalStorage for guest
        localStorage.setItem('bodhi_prefs', JSON.stringify(prefs));
    }
  };

  const handleLogout = () => {
    if (isGuest) {
        setIsGuest(false);
        setPreferences(null);
    } else {
        auth.signOut();
        setPreferences(null);
    }
  };

  if (loading) {
    return (
        <div className="h-screen w-full flex items-center justify-center bg-stone-50 text-orange-600">
            <Loader2 className="animate-spin" size={48} />
        </div>
    );
  }

  if (!isFirebaseConfigured() && !isGuest) {
    return (
        <Auth isGuest={isGuest} setIsGuest={setIsGuest} />
    );
  }

  if (!user && !isGuest) {
    return (
        <Auth isGuest={isGuest} setIsGuest={setIsGuest} />
    );
  }

  return (
    <Dashboard
      user={user}
      preferences={preferences}
      onOnboardingComplete={handleOnboardingComplete}
      onLogout={handleLogout}
      isGuest={isGuest}
    />
  );
}

export default App;
]]></content>
