import React, { useState, useEffect } from 'react';
import { User } from 'firebase/auth';
import { auth, getUserProfile, saveUserProfile } from './services/firebase';
import { onAuthStateChanged } from 'firebase/auth';
import { Loader2 } from 'lucide-react';
import Onboarding from './components/Onboarding';
import Dashboard from './components/Dashboard';
import Auth from './components/Auth';
import { UserPreferences } from './types';

function App() {
  const [user, setUser] = useState<User | null>(null);
  const [preferences, setPreferences] = useState<UserPreferences | null>(null);
  const [loading, setLoading] = useState(true);
  const [isGuest, setIsGuest] = useState(false);

  useEffect(() => {
    // Listen for authentication state changes
    const unsubscribe = onAuthStateChanged(auth, async (currentUser) => {
      setUser(currentUser);

      if (currentUser) {
        setIsGuest(false);
        // Fetch user data from Firestore
        const profile = await getUserProfile(currentUser.uid);
        if (profile) {
            setPreferences(profile);
        } else {
            // User exists in Auth but no profile yet (new user)
            setPreferences(null);
        }
      } else if (!isGuest) {
        // Only clear preferences if not switching to guest mode manually
        setPreferences(null);
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, [isGuest]);

  const handleGuestLogin = () => {
      setIsGuest(true);
      // Try to load local preferences if they exist
      try {
        const saved = localStorage.getItem('bodhi_prefs');
        if (saved) {
            setPreferences(JSON.parse(saved));
        } else {
            setPreferences(null);
        }
      } catch (e) {
          setPreferences(null);
      }
      setLoading(false);
  };

  const handleOnboardingComplete = async (prefs: UserPreferences) => {
    setPreferences(prefs);
    if (user && !isGuest) {
        // Save to Firestore
        await saveUserProfile(user.uid, prefs);
    } else {
        // Save to LocalStorage for guest
        localStorage.setItem('bodhi_prefs', JSON.stringify(prefs));
    }
  };

  const handleLogout = () => {
    if (isGuest) {
        setIsGuest(false);
        setPreferences(null);
    } else {
        auth.signOut();
        setPreferences(null);
    }
  };

  if (loading) {
    return (
        <div className="h-screen w-full flex items-center justify-center bg-stone-50 text-orange-600">
            <Loader2 className="animate-spin" size={48} />
        </div>
    );
  }

  if (!user && !isGuest) {
    return <Auth onGuestLogin={handleGuestLogin} />;
  }

  return (
    <div className="h-screen w-full bg-stone-50 text-stone-800 font-sans">
      {!preferences ? (
        <Onboarding onComplete={handleOnboardingComplete} />
      ) : (
        <Dashboard preferences={preferences} onLogout={handleLogout} />
      )}
    </div>
  );
}

export default App;

