import React, { useState, useEffect } from 'react';
import { Play, Pause, Square, Wind, Star, X } from 'lucide-react';
import { Language } from '../types';
import { getMeditationGuide, getMeditationFeedback } from '../services/geminiService';
import { UI_TEXT } from '../constants';
import { motion, AnimatePresence } from 'framer-motion';

interface MeditationHallProps {
  language: Language;
}

const MeditationHall: React.FC<MeditationHallProps> = ({ language }) => {
  const [duration, setDuration] = useState(5); // Minutes
  const [timeLeft, setTimeLeft] = useState(duration * 60);
  const [isActive, setIsActive] = useState(false);
  const [guidance, setGuidance] = useState<string>('');
  const [loadingGuidance, setLoadingGuidance] = useState(false);

  // Feedback States
  const [showFeedbackModal, setShowFeedbackModal] = useState(false);
  const [userReflection, setUserReflection] = useState('');
  const [aiResponse, setAiResponse] = useState('');
  const [loadingFeedback, setLoadingFeedback] = useState(false);

  const t = UI_TEXT[language];

  useEffect(() => {
    setTimeLeft(duration * 60);
  }, [duration]);

  useEffect(() => {
    let interval: ReturnType<typeof setInterval> | null = null;
    if (isActive && timeLeft > 0) {
      interval = setInterval(() => {
        setTimeLeft((prev) => prev - 1);
      }, 1000);
    } else if (timeLeft === 0) {
      setIsActive(false);
      if (interval) clearInterval(interval);
      setShowFeedbackModal(true); // Auto-open feedback on finish
    }
    return () => {
      if (interval) clearInterval(interval);
    };
  }, [isActive, timeLeft]);

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const handleStart = async () => {
    if (timeLeft === duration * 60 && !guidance) {
        setLoadingGuidance(true);
        const text = await getMeditationGuide('Mindfulness', duration, language);
        setGuidance(text);
        setLoadingGuidance(false);
    }
    setIsActive(true);
  };

  const toggleTimer = () => {
    if (!isActive) {
        handleStart();
    } else {
        setIsActive(false);
    }
  };

  const stopTimer = () => {
      setIsActive(false);
      setShowFeedbackModal(true);
  };

  const submitReflection = async () => {
      if (!userReflection.trim()) return;
      setLoadingFeedback(true);
      const feedback = await getMeditationFeedback(userReflection, language);
      setAiResponse(feedback);
      setLoadingFeedback(false);
  };

  const closeFeedback = () => {
      setShowFeedbackModal(false);
      setUserReflection('');
      setAiResponse('');
      setTimeLeft(duration * 60);
      setGuidance('');
  };

  return (
    <div className="relative flex flex-col items-center justify-center h-full p-6 bg-gradient-to-br from-stone-50 to-orange-50 rounded-2xl shadow-inner text-center">

      <div className="mb-8">
        <h2 className={`text-3xl font-serif text-stone-800 mb-2 ${language === 'si' ? 'font-sinhala' : ''}`}>
           {isActive ? (language === 'si' ? 'හුස්ම ගන්න...' : 'Breathe...') : (language === 'si' ? 'භාවනා ශාලාව' : 'Meditation Hall')}
        </h2>
        <p className="text-stone-500 flex items-center justify-center gap-2">
            <Wind size={16} /> 
            {language === 'si' ? 'මනස සන්සුන් කරගන්න' : 'Calm the mind'}
        </p>
      </div>

      {/* Timer Circle */}
      <div className="relative w-64 h-64 mb-8">
         <svg className="w-full h-full transform -rotate-90">
             <circle
               cx="128"
               cy="128"
               r="120"
               stroke="currentColor"
               strokeWidth="8"
               fill="transparent"
               className="text-stone-200"
             />
             <circle
               cx="128"
               cy="128"
               r="120"
               stroke="currentColor"
               strokeWidth="8"
               fill="transparent"
               strokeDasharray={2 * Math.PI * 120}
               strokeDashoffset={2 * Math.PI * 120 * (1 - timeLeft / (duration * 60))}
               className="text-orange-400 transition-all duration-1000 ease-linear"
             />
         </svg>
         <div className="absolute top-0 left-0 w-full h-full flex items-center justify-center flex-col">
            <span className="text-5xl font-mono text-stone-700 font-bold">{formatTime(timeLeft)}</span>
         </div>
      </div>

      {/* Controls */}
      <div className="flex items-center space-x-6 mb-8">
        {!isActive ? (
             <button onClick={toggleTimer} className="w-16 h-16 bg-orange-600 rounded-full flex items-center justify-center text-white shadow-lg hover:bg-orange-700 transition-all transform hover:scale-105">
                <Play fill="currentColor" />
             </button>
        ) : (
             <button onClick={toggleTimer} className="w-16 h-16 bg-stone-200 rounded-full flex items-center justify-center text-stone-700 shadow-lg hover:bg-stone-300 transition-all">
                <Pause fill="currentColor" />
             </button>
        )}
        {isActive && (
            <button onClick={stopTimer} className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center text-red-600 hover:bg-red-200 transition-all">
                <Square size={16} fill="currentColor" />
            </button>
        )}
      </div>

      {/* Guidance */}
      <div className="max-w-md w-full min-h-[80px]">
          {loadingGuidance ? (
              <p className="text-stone-400 italic animate-pulse">Preparing guidance...</p>
          ) : (
            guidance && (
                <div className="bg-white/80 p-4 rounded-xl border border-orange-100 shadow-sm">
                    <p className={`text-stone-700 italic font-serif ${language === 'si' ? 'font-sinhala' : ''}`}>"{guidance}"</p>
                </div>
            )
          )}
      </div>

      {/* Settings */}
      {!isActive && (
          <div className="mt-4 flex items-center space-x-4">
              <span className="text-stone-500 text-sm">{t.duration}:</span>
              {[5, 10, 20].map(m => (
                  <button 
                    key={m}
                    onClick={() => setDuration(m)}
                    className={`px-3 py-1 rounded-full text-sm border ${duration === m ? 'bg-orange-100 border-orange-400 text-orange-900' : 'bg-white border-stone-200 text-stone-600'}`}
                  >
                      {m}m
                  </button>
              ))}
          </div>
      )}

      {/* Feedback Modal */}
      <AnimatePresence>
          {showFeedbackModal && (
              <motion.div 
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="absolute inset-0 bg-white/95 backdrop-blur-sm z-50 flex items-center justify-center p-6 rounded-2xl"
              >
                  <div className="max-w-md w-full text-left">
                      <div className="flex justify-between items-center mb-4">
                          <h3 className={`text-xl font-bold text-stone-800 ${language === 'si' ? 'font-sinhala' : ''}`}>
                              {t.feedbackTitle}
                          </h3>
                          <button onClick={closeFeedback} className="text-stone-400 hover:text-stone-600"><X /></button>
                      </div>

                      {!aiResponse ? (
                          <>
                            <textarea
                                value={userReflection}
                                onChange={(e) => setUserReflection(e.target.value)}
                                placeholder={t.feedbackPlaceholder}
                                className={`w-full p-4 border border-stone-200 rounded-xl mb-4 bg-stone-50 focus:outline-none focus:border-orange-300 h-32 resize-none ${language === 'si' ? 'font-sinhala' : ''}`}
                            />
                            <button 
                                onClick={submitReflection}
                                disabled={loadingFeedback}
                                className="w-full bg-orange-600 text-white py-3 rounded-xl hover:bg-orange-700 transition-colors disabled:opacity-50"
                            >
                                {loadingFeedback ? 'Processing...' : 'Reflect'}
                            </button>
                            <button onClick={closeFeedback} className="w-full mt-2 text-stone-500 py-2">Skip</button>
                          </>
                      ) : (
                          <div className="bg-orange-50 p-6 rounded-xl border border-orange-100">
                              <Star className="text-orange-400 mb-2" size={24} />
                              <p className={`text-stone-800 font-serif italic mb-6 ${language === 'si' ? 'font-sinhala' : ''}`}>
                                  "{aiResponse}"
                              </p>
                              <button onClick={closeFeedback} className="w-full bg-stone-800 text-white py-3 rounded-xl hover:bg-stone-900">
                                  Close
                              </button>
                          </div>
                      )}
                  </div>
              </motion.div>
          )}
      </AnimatePresence>
    </div>
  );
};

export default MeditationHall;

import React, { useState, useRef, useEffect } from 'react';
import { Send, User, Bot, Loader2, Sparkles, Scale } from 'lucide-react';
import { ChatMessage, Language } from '../types';
import { createChatSession } from '../services/geminiService';
import { UI_TEXT } from '../constants';
import { Chat } from '@google/genai';

interface ChatInterfaceProps {
  language: Language;
  userGoals: string[];
}

const ChatInterface: React.FC<ChatInterfaceProps> = ({ language, userGoals }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [chatSession, setChatSession] = useState<Chat | null>(null);
  const [isDebateMode, setIsDebateMode] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const t = UI_TEXT[language];

  // Initialize or Reset Session when Mode/Language changes
  useEffect(() => {
    const session = createChatSession(language, userGoals, isDebateMode);
    setChatSession(session);

    // Initial greeting
    const greetingText = isDebateMode 
      ? (language === 'si' ? "අපි ධර්ම සාකච්ඡාවක් කරමු. ඔබේ තර්කය ඉදිරිපත් කරන්න." : "Let us debate the Dhamma. Present your view.")
      : (language === 'si' ? "තෙරුවන් සරණයි! මම භන්තේ බෝධි. ඔබට ධර්මය සම්බන්ධව ඇති ගැටලු මොනවාද?" : "Namo Buddhaya! I am Bhante Bodhi. How may I guide you on the Dhamma path today?");

    setMessages([{
        id: 'init',
        role: 'model',
        text: greetingText,
        timestamp: Date.now()
    }]);
  }, [language, userGoals, isDebateMode]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || !chatSession) return;

    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      text: input,
      timestamp: Date.now()
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    try {
      const result = await chatSession.sendMessage({ message: userMsg.text });
      const text = result.text; 

      const botMsg: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: text || (language === 'si' ? "මට එය තේරුම් ගැනීමට අපහසුයි. කරුණාකර නැවත අසන්න." : "I apologize, I could not understand clearly. Please ask again."),
        timestamp: Date.now()
      };
      setMessages(prev => [...prev, botMsg]);
    } catch (error) {
      console.error("Chat error:", error);
      const errorMsg: ChatMessage = {
         id: (Date.now() + 1).toString(),
         role: 'model',
         text: language === 'si' ? "සමාවන්න, තාක්ෂණික දෝෂයක් සිදු විය." : "Apologies, I encountered a disturbance. Please try again.",
         timestamp: Date.now()
      };
      setMessages(prev => [...prev, errorMsg]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="flex flex-col h-full bg-stone-50 rounded-2xl overflow-hidden shadow-inner border border-stone-200">
      {/* Header */}
      <div className={`p-4 flex items-center justify-between border-b border-orange-200 ${isDebateMode ? 'bg-stone-800 text-white' : 'bg-orange-100 text-stone-800'}`}>
        <div className="flex items-center">
            <div className={`w-10 h-10 rounded-full flex items-center justify-center mr-3 border-2 border-white ${isDebateMode ? 'bg-stone-700' : 'bg-orange-200'}`}>
                <span className="text-xl">{isDebateMode ? '⚖️' : '🧘‍♂️'}</span>
            </div>
            <div>
            <h3 className={`font-serif font-bold ${language === 'si' ? 'font-sinhala' : ''}`}>
                {isDebateMode ? (language === 'si' ? 'ධර්ම විවාදය' : 'Dhamma Debate') : t.monkPersona}
            </h3>
            <p className="text-xs opacity-70 flex items-center">
                <Sparkles size={10} className="mr-1" /> 
                AI Guide (Gemini)
            </p>
            </div>
        </div>

        <button 
            onClick={() => setIsDebateMode(!isDebateMode)}
            className={`flex items-center gap-2 px-3 py-1 rounded-full text-xs font-bold transition-all ${isDebateMode ? 'bg-stone-600 hover:bg-stone-500' : 'bg-white hover:bg-orange-50 shadow-sm'}`}
        >
            <Scale size={14} />
            <span>{t.debateMode}</span>
        </button>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.map((msg) => (
          <div 
            key={msg.id} 
            className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
          >
            <div className={`max-w-[80%] rounded-2xl p-4 shadow-sm ${
              msg.role === 'user' 
                ? 'bg-orange-600 text-white rounded-tr-none' 
                : 'bg-white text-stone-800 border border-stone-100 rounded-tl-none font-serif'
            }`}>
                <p className={`whitespace-pre-wrap leading-relaxed ${language === 'si' ? 'font-sinhala' : ''}`}>{msg.text}</p>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
             <div className="bg-white rounded-2xl rounded-tl-none p-4 shadow-sm border border-stone-100 flex items-center space-x-2">
                <Loader2 size={16} className="animate-spin text-orange-500" />
                <span className="text-sm text-stone-400 italic">Thinking...</span>
             </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input */}
      <div className="p-4 bg-white border-t border-stone-200">
        <div className="flex items-center space-x-2 bg-stone-100 rounded-full px-4 py-2 border border-transparent focus-within:border-orange-300 focus-within:bg-white transition-all">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder={t.chatPlaceholder}
            className={`flex-1 bg-transparent border-none focus:outline-none text-stone-800 placeholder-stone-400 ${language === 'si' ? 'font-sinhala' : ''}`}
            disabled={isLoading}
          />
          <button 
            onClick={handleSend} 
            disabled={isLoading || !input.trim()}
            className="p-2 bg-orange-600 text-white rounded-full hover:bg-orange-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
          >
            <Send size={18} />
          </button>
        </div>
      </div>
    </div>
  );
};

export default ChatInterface;

import React, { useEffect, useState, useRef } from 'react';
import { MessageCircle, Brain, BookOpen, PenTool, MapPin, Menu, X, Sun, LogOut, Download, Upload, Calendar, GraduationCap } from 'lucide-react';
import { UserPreferences, AppView, DailyDrop } from '../types';
import { UI_TEXT } from '../constants';
import ChatInterface from './ChatInterface';
import MeditationHall from './MeditationHall';
import DhammaClassroom from './DhammaClassroom';
import KarmaJournal from './KarmaJournal';
import BuddhistCalendar from './BuddhistCalendar';
import { generateDailyDharma } from '../services/geminiService';
import { auth, saveUserProfile } from '../services/firebase';

interface DashboardProps {
  preferences: UserPreferences;
  onLogout: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ preferences, onLogout }) => {
  const [currentView, setCurrentView] = useState<AppView>(AppView.DASHBOARD);
  const [dailyDrop, setDailyDrop] = useState<DailyDrop | null>(null);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const t = UI_TEXT[preferences.language];

  useEffect(() => {
    const fetchDaily = async () => {
        if (preferences.receiveDailyDrops) {
            const drop = await generateDailyDharma(preferences.language);
            setDailyDrop(drop);
        }
    };
    fetchDaily();
  }, [preferences.receiveDailyDrops, preferences.language]);

  const handleBackup = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(preferences));
    const downloadAnchorNode = document.createElement('a');
    downloadAnchorNode.setAttribute("href", dataStr);
    downloadAnchorNode.setAttribute("download", "bodhipath_backup.json");
    document.body.appendChild(downloadAnchorNode);
    downloadAnchorNode.click();
    downloadAnchorNode.remove();
  };

  const handleRestoreClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        const text = e.target?.result as string;
        const parsed = JSON.parse(text);
        // Simple validation check
        if (parsed && parsed.language && Array.isArray(parsed.goals)) {
            // If logged in, save to Firestore
            if (auth.currentUser) {
                await saveUserProfile(auth.currentUser.uid, parsed);
            } else {
                // If guest, save to LocalStorage
                localStorage.setItem('bodhi_prefs', JSON.stringify(parsed));
            }
            alert(preferences.language === 'si' ? 'දත්ත සාර්ථකව ප්‍රතිසාධනය කරන ලදී. පිටුව නැවත පූරණය වේ.' : 'Data restored successfully. Reloading...');
            window.location.reload();
        } else {
            alert("Invalid backup file.");
        }
      } catch (err) {
        console.error(err);
        alert("Failed to parse backup file.");
      }
    };
    reader.readAsText(file);
  };

  const NavItem = ({ view, icon: Icon, label }: { view: AppView, icon: any, label: string }) => (
    <button 
      onClick={() => { setCurrentView(view); setSidebarOpen(false); }}
      className={`w-full flex items-center space-x-3 p-3 rounded-xl transition-all ${
        currentView === view 
        ? 'bg-orange-100 text-orange-900 font-medium' 
        : 'text-stone-600 hover:bg-stone-100'
      }`}
    >
      <Icon size={20} />
      <span className={preferences.language === 'si' ? 'font-sinhala' : ''}>{label}</span>
    </button>
  );

  return (
    <div className="flex h-screen bg-stone-50 overflow-hidden">

      {/* Sidebar (Mobile Overlay + Desktop) */}
      <div className={`fixed inset-0 bg-black/20 z-20 md:hidden ${sidebarOpen ? 'block' : 'hidden'}`} onClick={() => setSidebarOpen(false)} />

      <aside className={`fixed md:relative z-30 w-64 h-full bg-white border-r border-stone-200 transform transition-transform duration-300 md:translate-x-0 ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'} flex flex-col`}>
        <div className="p-6 flex items-center justify-between">
           <div className="flex items-center gap-2">
               <span className="text-2xl">🌼</span>
               <h1 className="text-xl font-serif font-bold text-stone-800">BodhiPath</h1>
           </div>
           <button onClick={() => setSidebarOpen(false)} className="md:hidden text-stone-500">
               <X size={20} />
           </button>
        </div>

        <nav className="px-4 space-y-1 flex-1 overflow-y-auto">
          <NavItem view={AppView.DASHBOARD} icon={Sun} label={t.home} />
          <NavItem view={AppView.CLASSROOM} icon={GraduationCap} label={t.classroom} />
          <NavItem view={AppView.CHAT} icon={MessageCircle} label={t.chat} />
          <NavItem view={AppView.MEDITATION} icon={Brain} label={t.meditate} />
          <NavItem view={AppView.JOURNAL} icon={PenTool} label={t.journal} />
          <NavItem view={AppView.CALENDAR} icon={Calendar} label={t.calendar} />
          <NavItem view={AppView.SUTTA} icon={BookOpen} label={t.suttaExplorer} />
          <NavItem view={AppView.TEMPLE} icon={MapPin} label={t.temple} />
        </nav>

        <div className="p-4 space-y-2 border-t border-stone-100">
             {/* Data Management */}
             <p className="px-3 text-xs font-bold text-stone-400 uppercase tracking-wider mb-1">
                {auth.currentUser ? 'Account' : 'Guest Mode'}
             </p>

             <button onClick={handleBackup} className="w-full flex items-center space-x-3 p-3 rounded-xl text-stone-600 hover:bg-stone-100 transition-colors">
                <Download size={18} />
                <span className={`text-sm ${preferences.language === 'si' ? 'font-sinhala' : ''}`}>{t.backupData}</span>
             </button>

             <button onClick={handleRestoreClick} className="w-full flex items-center space-x-3 p-3 rounded-xl text-stone-600 hover:bg-stone-100 transition-colors">
                <Upload size={18} />
                <span className={`text-sm ${preferences.language === 'si' ? 'font-sinhala' : ''}`}>{t.restoreData}</span>
             </button>
             <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" accept=".json" />

             {/* Sign Out Button */}
             <button 
                onClick={() => {
                    if (window.confirm("Are you sure you want to exit?")) {
                        onLogout();
                    }
                }}
                className="w-full flex items-center space-x-3 p-3 rounded-xl text-stone-400 hover:bg-red-50 hover:text-red-600 transition-colors mt-2"
             >
                <LogOut size={18} />
                <span className={`text-sm ${preferences.language === 'si' ? 'font-sinhala' : ''}`}>
                   {auth.currentUser ? 'Sign Out' : 'Exit Guest'}
                </span>
             </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-full overflow-hidden relative">
        {/* Mobile Header */}
        <header className="md:hidden h-16 bg-white border-b border-stone-200 flex items-center px-4 justify-between shrink-0">
            <button onClick={() => setSidebarOpen(true)} className="text-stone-600">
                <Menu />
            </button>
            <span className="font-serif font-bold text-stone-800">BodhiPath</span>
            <div className="w-6" /> {/* Spacer */}
