import React, { useState, useEffect } from 'react';
import { User, onAuthStateChanged, signOut } from 'firebase/auth';
import { auth, getUserProfile, saveUserProfile } from './services/firebase';
import { Loader2 } from 'lucide-react';
import Onboarding from './components/Onboarding';
import Dashboard from './components/Dashboard';
import Auth from './components/Auth';
import { UserPreferences } from './types';

function App() {
  const [user, setUser] = useState<User | null>(null);
  const [preferences, setPreferences] = useState<UserPreferences | null>(null);
  const [loading, setLoading] = useState(true);
  const [isGuest, setIsGuest] = useState(false);

  useEffect(() => {
    // Listen for authentication state changes
    const unsubscribe = onAuthStateChanged(auth, async (currentUser) => {
      setUser(currentUser);

      if (currentUser) {
        setIsGuest(false);
        // Fetch user data from Firestore
        const profile = await getUserProfile(currentUser.uid);
        if (profile) {
            setPreferences(profile);
        } else {
            // User exists in Auth but no profile yet (new user)
            setPreferences(null);
        }
      } else if (!isGuest) {
        // Only clear preferences if not switching to guest mode manually
        setPreferences(null);
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, [isGuest]);

  const handleGuestLogin = () => {
      setIsGuest(true);
      // Try to load local preferences if they exist
      try {
        const saved = localStorage.getItem('bodhi_prefs');
        if (saved) {
            setPreferences(JSON.parse(saved));
        } else {
            setPreferences(null);
        }
      } catch (e) {
          setPreferences(null);
      }
      setLoading(false);
  };

  const handleOnboardingComplete = async (prefs: UserPreferences) => {
    await handleUpdatePreferences(prefs);
  };

  const handleUpdatePreferences = async (newPrefs: UserPreferences) => {
      setPreferences(newPrefs);
      if (user && !isGuest) {
          // Save to Firestore
          await saveUserProfile(user.uid, newPrefs);
      } else {
          // Save to LocalStorage for guest
          localStorage.setItem('bodhi_prefs', JSON.stringify(newPrefs));
      }
  };

  const handleLogout = async () => {
    if (isGuest) {
        setIsGuest(false);
        setPreferences(null);
    } else {
        try {
            await signOut(auth);
            // We rely on onAuthStateChanged to clear preferences and user state
            // This prevents the "Onboarding" screen from flashing before the Auth screen appears
        } catch (error) {
            console.error("Logout failed:", error);
        }
    }
  };

  if (loading) {
    return (
        <div className="h-screen w-full flex items-center justify-center bg-stone-50 text-orange-600">
            <Loader2 className="animate-spin" size={48} />
        </div>
    );
  }

  if (!user && !isGuest) {
    return <Auth onGuestLogin={handleGuestLogin} />;
  }

  return (
    <div className="h-screen w-full bg-stone-50 text-stone-800 font-sans">
      {!preferences ? (
        <Onboarding onComplete={handleOnboardingComplete} />
      ) : (
        <Dashboard preferences={preferences} onLogout={handleLogout} onUpdatePreferences={handleUpdatePreferences} />
      )}
    </div>
  );
}

export default App;

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { signInWithEmailAndPassword, createUserWithEmailAndPassword } from 'firebase/auth';
import { auth, signInWithGoogle } from '../services/firebase';
import { Loader2, Mail, Lock, LogIn, User, AlertCircle } from 'lucide-react';

interface AuthProps {
  onGuestLogin: () => void;
}

const Auth: React.FC<AuthProps> = ({ onGuestLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleEmailAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      if (isLogin) {
        await signInWithEmailAndPassword(auth, email, password);
      } else {
        await createUserWithEmailAndPassword(auth, email, password);
      }
    } catch (err: any) {
      if (err.message.includes('auth/api-key-not-valid')) {
        setError("Firebase not configured. Please add API Key to services/firebase.ts or use Guest Mode.");
      } else {
        setError(err.message.replace('Firebase: ', ''));
      }
    } finally {
      setLoading(false);
    }
  };

  const handleGoogleAuth = async () => {
    setError('');
    try {
      await signInWithGoogle();
    } catch (err: any) {
      console.error(err);
      if (err.code === 'auth/unauthorized-domain') {
        setError(`Domain not authorized: ${window.location.hostname}. Please add this domain to Firebase Console > Auth > Settings, or use Guest Mode.`);
      } else if (err.message && err.message.includes('auth/api-key-not-valid')) {
        setError("Firebase API Key is missing/invalid. Try Guest Mode.");
      } else {
        setError("Failed to sign in. " + (err.message || "Unknown error"));
