                    <span>{error}</span>
                </div>
            )}

            <button 
                type="submit" 
                disabled={loading}
                className="w-full bg-stone-800 hover:bg-stone-900 text-white py-3 rounded-full font-medium transition-all shadow-lg flex justify-center items-center"
            >
