interface DashboardProps {
  preferences: UserPreferences;
  onLogout: () => void;
  onUpdatePreferences: (newPrefs: UserPreferences) => Promise<void>;
}

const Dashboard: React.FC<DashboardProps> = ({ preferences, onLogout, onUpdatePreferences }) => {
