                <div className="h-full max-w-4xl mx-auto">
                    <KarmaJournal language={preferences.language} />
                </div>
            )}

            {/* VIEW: CLASSROOM */}
            {currentView === AppView.CLASSROOM && (
                <DhammaClassroom language={preferences.language} />
