import { initializeApp } from "firebase/app";
import { getAuth, GoogleAuthProvider, signInWithPopup } from "firebase/auth";
import { getFirestore, doc, setDoc, getDoc } from "firebase/firestore";
import { UserPreferences } from "../types";

// Robust Environment Loader
// 1. Accepts the Vite explicit value (required for Vercel build replacement)
// 2. Falls back to process.env (for standard Node/Local environments)
// 3. Handles undefined objects gracefully
const getEnv = (key: string, viteValue: string | undefined) => {
    // If Vite replaced this during build, use it
    if (viteValue) return viteValue;

    // Fallback: Check process.env safely
    try {
        // @ts-ignore
        if (typeof process !== 'undefined' && process.env) {
            // @ts-ignore
            return process.env[key];
        }
    } catch (e) {
        // Ignore errors if process is not defined
    }

    return undefined;
};

// Security: Load config
const firebaseConfig = {
  apiKey: getEnv('VITE_FIREBASE_API_KEY', (import.meta as any).env?.VITE_FIREBASE_API_KEY),
  authDomain: getEnv('VITE_FIREBASE_AUTH_DOMAIN', (import.meta as any).env?.VITE_FIREBASE_AUTH_DOMAIN),
  projectId: getEnv('VITE_FIREBASE_PROJECT_ID', (import.meta as any).env?.VITE_FIREBASE_PROJECT_ID),
  storageBucket: getEnv('VITE_FIREBASE_STORAGE_BUCKET', (import.meta as any).env?.VITE_FIREBASE_STORAGE_BUCKET),
  messagingSenderId: getEnv('VITE_FIREBASE_MESSAGING_SENDER_ID', (import.meta as any).env?.VITE_FIREBASE_MESSAGING_SENDER_ID),
  appId: getEnv('VITE_FIREBASE_APP_ID', (import.meta as any).env?.VITE_FIREBASE_APP_ID),
  measurementId: getEnv('VITE_FIREBASE_MEASUREMENT_ID', (import.meta as any).env?.VITE_FIREBASE_MEASUREMENT_ID)
};

// Validate config
const isConfigValid = !!firebaseConfig.apiKey;

if (!isConfigValid) {
  console.warn("Firebase config missing. Please check your .env file or Vercel environment variables.");
}

// Initialize Firebase
// If config is invalid, we initialize with a dummy config. This prevents the "auth/invalid-api-key" error 
// from crashing the app immediately, allowing the UI to render so users can access Guest Mode.
const app = initializeApp(isConfigValid ? firebaseConfig : { 
    apiKey: "AIzaSy_DUMMY_KEY_PREVENTS_CRASH", 
    authDomain: "dummy.firebaseapp.com",
    projectId: "dummy-project",
    appId: "1:123456789:web:dummy"
});

export const auth = getAuth(app);
export const db = getFirestore(app);
export const googleProvider = new GoogleAuthProvider();

export const signInWithGoogle = async () => {
  if (!isConfigValid) throw new Error("Firebase configuration missing. Cannot sign in with Google.");
  try {
    await signInWithPopup(auth, googleProvider);
  } catch (error) {
    console.error("Error signing in with Google", error);
    throw error;
  }
};

// Helper to separate guest data from auth user fallback data
const getStorageKey = (uid: string) => `bodhi_user_${uid}`;

export const saveUserProfile = async (uid: string, data: UserPreferences) => {
    if (!isConfigValid) {
        // Fallback for missing config (Guest mode mostly)
        localStorage.setItem(getStorageKey(uid), JSON.stringify(data));
        return;
    }
    try {
        await setDoc(doc(db, "users", uid), data, { merge: true });
    } catch (error: any) {
        // Fallback to localStorage if permission denied or unavailable
        if (error.code === 'permission-denied' || error.code === 'unavailable') {
            localStorage.setItem(getStorageKey(uid), JSON.stringify(data));
        } else {
            console.error("Error saving user profile", error);
            throw error;
        }
    }
};

export const getUserProfile = async (uid: string): Promise<UserPreferences | null> => {
    if (!isConfigValid) {
         const localData = localStorage.getItem(getStorageKey(uid));
         return localData ? JSON.parse(localData) : null;
    }
    try {
        const docRef = doc(db, "users", uid);
        const docSnap = await getDoc(docRef);
        if (docSnap.exists()) {
            return docSnap.data() as UserPreferences;
        }
        return null;
    } catch (error: any) {
        if (error.code === 'permission-denied' || error.code === 'unavailable') {
             const localData = localStorage.getItem(getStorageKey(uid));
             if (localData) {
                 return JSON.parse(localData);
             }
             return null;
        }
        console.error("Error fetching user profile", error);
        return null;
    }
};

