      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
            type: Type.OBJECT,
            properties: {
                quote: { type: Type.STRING },
                source: { type: Type.STRING },
                reflection: { type: Type.STRING }
