                      <span className="text-3xl">🌑</span>
                      <span className="font-bold text-stone-700">{language === 'si' ? 'නැහැ' : 'No'}</span>
                   </button>
                </div>
             </motion.div>
          )}

          {/* Step 6: Final */}
          {step === 6 && (
             <motion.div
                key="step6"
                variants={containerVariants}
                initial="hidden"
                animate="visible"
                exit="exit"
