                            <em>"Where are the nearest temples?"</em>
                        </p>
                        <button onClick={() => setCurrentView(AppView.CHAT)} className="bg-stone-800 text-white px-8 py-3 rounded-full hover:bg-stone-900 transition-colors">
                            Go to Chat
                        </button>
                    </div>
                </div>
            )}

            {currentView === AppView.TERMS && (
                <LegalView type="terms" language={preferences.language} onBack={() => setCurrentView(AppView.DASHBOARD)} />
            )}

            {currentView === AppView.PRIVACY && (
                <LegalView type="privacy" language={preferences.language} onBack={() => setCurrentView(AppView.DASHBOARD)} />
            )}
        </div>
      </main>
    </div>
  );
};

