    const text = `"${drop.quote}" — ${drop.source}\n\nReflection: ${drop.reflection}\n\nShared from BodhiPath`;
    if (navigator.share) {
      navigator.share({ title: 'Daily Wisdom', text: text, url: window.location.origin });
