  const t = UI_TEXT[preferences.language];

  useEffect(() => {
    const handleDailyWisdom = async () => {
        if (!preferences.receiveDailyDrops) return;

        // Load history and today's drop from local storage
        const savedHistory = localStorage.getItem('bodhi_drop_history');
        const history: DailyDrop[] = savedHistory ? JSON.parse(savedHistory) : [];
        setDropHistory(history);

        const savedToday = localStorage.getItem('bodhi_drop_today');
        let today: DailyDrop | null = savedToday ? JSON.parse(savedToday) : null;

        const now = Date.now();
        const oneDay = 24 * 60 * 60 * 1000;

        // Check if today's drop is expired or non-existent
        if (!today || (now - today.timestamp > oneDay)) {
            // If it's old, move it to history before fetching new
            if (today && !history.find(d => d.timestamp === today?.timestamp)) {
                const updatedHistory = [today, ...history].slice(0, 10); // Keep last 10
                setDropHistory(updatedHistory);
                localStorage.setItem('bodhi_drop_history', JSON.stringify(updatedHistory));
            }

            // Generate new drop
            const newDropData = await generateDailyDharma(preferences.language);
            const newDrop: DailyDrop = { ...newDropData, timestamp: now };
            setDailyDrop(newDrop);
            localStorage.setItem('bodhi_drop_today', JSON.stringify(newDrop));
        } else {
            setDailyDrop(today);
        }
    };
    handleDailyWisdom();
