      <div className="flex items-center space-x-3">
        <Icon size={20} />
        <span className={preferences.language === 'si' ? 'font-sinhala' : ''}>{label}</span>
      </div>
      {hasUpdate && <div className="w-2 h-2 bg-orange-500 rounded-full animate-pulse" />}
    </button>
  );

