import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { signInWithEmailAndPassword, createUserWithEmailAndPassword } from 'firebase/auth';
import { auth, signInWithGoogle } from '../services/firebase';
import { Loader2, Mail, Lock, LogIn, User, AlertCircle } from 'lucide-react';
import Logo from './Logo';

interface AuthProps {
  onGuestLogin: () => void;
}

const Auth: React.FC<AuthProps> = ({ onGuestLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleEmailAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      if (isLogin) {
        await signInWithEmailAndPassword(auth, email, password);
      } else {
        await createUserWithEmailAndPassword(auth, email, password);
      }
    } catch (err: any) {
      if (err.message.includes('auth/api-key-not-valid')) {
        setError("Firebase not configured. Please use Guest Mode.");
      } else {
        setError(err.message.replace('Firebase: ', ''));
      }
    } finally {
      setLoading(false);
    }
  };

  const handleGoogleAuth = async () => {
    setError('');
    try {
      await signInWithGoogle();
    } catch (err: any) {
      console.error(err);
      setError("Failed to sign in. " + (err.message || "Unknown error"));
    }
  };

  return (
    <div className="py-20 flex items-center justify-center p-6 relative overflow-hidden">
      <motion.div 
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="bg-white rounded-3xl p-8 shadow-xl w-full max-w-md z-10 border border-stone-100"
      >
        <div className="text-center mb-8">
            <div className="mb-4 flex justify-center">
                <Logo className="w-20 h-20 drop-shadow-sm" />
            </div>
            <h1 className="text-3xl font-serif font-bold text-stone-800 tracking-tight">App Portal</h1>
            <p className="text-stone-500 mt-2 font-serif italic">Begin your journey within.</p>
        </div>

        <form onSubmit={handleEmailAuth} className="space-y-4">
            <div className="bg-stone-50 rounded-xl p-3 border border-stone-200 flex items-center">
                <Mail className="text-stone-400 mr-3" size={20} />
                <input 
                    type="email" 
                    placeholder="Email" 
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    className="bg-transparent w-full outline-none text-stone-800 placeholder-stone-400"
                    required
                />
            </div>
            <div className="bg-stone-50 rounded-xl p-3 border border-stone-200 flex items-center">
                <Lock className="text-stone-400 mr-3" size={20} />
                <input 
                    type="password" 
                    placeholder="Password" 
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    className="bg-transparent w-full outline-none text-stone-800 placeholder-stone-400"
                    required
                    minLength={6}
                />
            </div>

            {error && (
                <div className="bg-red-50 text-red-600 p-3 rounded-lg text-sm text-center flex items-center justify-center gap-2">
                    <AlertCircle size={16} className="shrink-0" />
                    <span>{error}</span>
                </div>
            )}

            <button 
                type="submit" 
                disabled={loading}
                className="w-full bg-stone-800 hover:bg-stone-900 text-white py-3 rounded-xl font-medium transition-all shadow-lg flex justify-center items-center"
            >
                {loading ? <Loader2 className="animate-spin" size={20} /> : (isLogin ? 'Sign In' : 'Create Account')}
            </button>
        </form>

        <div className="my-6 flex items-center justify-between">
            <div className="h-px bg-stone-200 w-full"></div>
            <span className="px-3 text-stone-400 text-sm">or</span>
            <div className="h-px bg-stone-200 w-full"></div>
        </div>

        <button 
            onClick={handleGoogleAuth}
            type="button"
            className="w-full bg-white border border-stone-300 hover:bg-stone-50 text-stone-700 py-3 rounded-xl font-medium transition-all flex items-center justify-center space-x-2 mb-3 shadow-sm"
        >
             <svg className="w-5 h-5" viewBox="0 0 24 24">
                <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z" fill="#4285F4" />
                <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853" />
                <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" fill="#FBBC05" />
                <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335" />
              </svg>
            <span>Continue with Google</span>
        </button>

        <button 
            onClick={onGuestLogin}
            type="button"
            className="w-full bg-orange-50 border border-orange-200 hover:bg-orange-100 text-orange-900 py-3 rounded-xl font-medium transition-all flex items-center justify-center space-x-2 shadow-sm"
        >
             <User className="w-5 h-5" />
            <span>Continue as Guest</span>
        </button>

        <div className="mt-6 text-center">
            <button 
                onClick={() => setIsLogin(!isLogin)} 
                className="text-stone-500 hover:text-stone-700 text-sm font-medium"
            >
                {isLogin ? "Don't have an account? Sign Up" : "Already have an account? Sign In"}
            </button>
        </div>
      </motion.div>
    </div>
  );
};

export default Auth;

