          {/* Step 2: Goals */}
          {step === 2 && (
            <motion.div
               key="step2"
               variants={containerVariants}
               initial="hidden"
               animate="visible"
               exit="exit"
               className="bg-white rounded-3xl p-8 shadow-xl"
